import scala.concurrent.{ExecutionContext, Future}

final class Downloader(client: HttpClient)(using ec: ExecutionContext):
  def fetch(url: String): Future[String] = Future(client.get(url))

  def fetchThen(url: String)(onDone: String => Unit, onError: Throwable => Unit): Unit =
    fetch(url).onComplete {
      case scala.util.Success(body) => onDone(body)
      case scala.util.Failure(err)  => onError(err)
    }
